<?php
require_once dirname(__DIR__).'/src/bootstrap.php';$sent=false;$error=null;
if(request_method('POST')){Csrf::verify();$email=strtolower(trim($_POST['email']??''));$s=db()->prepare("SELECT * FROM users WHERE email=? AND role='donor' AND email_verified_at IS NULL LIMIT 1");$s->execute([$email]);$u=$s->fetch();if($u){try{$dev=(new VerificationService())->sendEmailVerification($u);if($dev)$_SESSION['dev_email_verify_url']=$dev;}catch(Throwable $e){$error='The verification message could not be prepared.';}}$sent=true;}
$pageTitle='Resend Verification';require dirname(__DIR__).'/src/templates/header.php';?>
<div class="form-card narrow"><h1>Resend email verification</h1><?php if($error):?><div class="error-list"><?=e($error)?></div><?php endif;?><?php if($sent):?><div class="flash success">If an unverified donor account exists for that email, a new verification message has been prepared.</div><?php if(!empty($_SESSION['dev_email_verify_url'])):?><p><a class="btn" href="<?=e((string)$_SESSION['dev_email_verify_url'])?>">Open local verification link</a></p><?php endif;?><?php else:?><form method="post"><?=Csrf::field()?><div class="field"><label>Email</label><input type="email" name="email" required></div><button class="btn">Prepare Verification</button></form><?php endif;?></div>
<?php require dirname(__DIR__).'/src/templates/footer.php';?>
